while (!current->is_leaf) {
    Node* next = nullptr;
    if (current->keys.empty()) {
        next = current->children[0];
    } else {
        auto it = std::upper_bound(current->keys.begin(), current->keys.end(), key);
        int index = std::distance(current->keys.begin(), it);
        next = current->children[index];
    }
    current = next;
}
return current;
